        public ReadOnlyMemorySlice<Byte>? GLOB => _GLOBLocation.HasValue ? HeaderTranslation.ExtractSubrecordMemory(_recordData, _GLOBLocation.Value, _package.MetaData.Constants) : default(ReadOnlyMemorySlice<byte>?);
